semantics:
[
  {
    "name": "file",
    "type": "image",
    "label": "Image",
    "importance": "high",
    "disableCopyright": true
  },
  {
    "name": "decorative",
    "type": "boolean",
    "label": "Decorative only",
    "default": false,
    "description": "Enable this option if the image is purely decorative and does not add any information to the content on the page. It will be ignored by screen readers and not given any alternative text."
  },
  {
    "name": "alt",
    "type": "text",
    "label": "Alternative text",
    "importance": "high",
    "description": "Required. If the browser can't load the image this text will be displayed instead. Also used by \"text-to-speech\" readers.",
    "widget": "showWhen",
    "showWhen": {
      "rules": [
        {
          "field": "decorative",
          "equals": false
        }
      ],
      "nullWhenHidden": true
    }
  },
  {
    "name": "title",
    "type": "text",
    "label": "Hover text",
    "importance": "low",
    "description": "Optional. This text is displayed when the users hover their pointing device over the image.",
    "optional": true
  },
  {
    "name": "contentName",
    "type": "text",
    "label": "Image content name",
    "importance": "low",
    "common": true,
    "default": "Image"
  },
  {
    "name": "expandImage",
    "type": "text",
    "label": "Expand Image",
    "importance": "low",
    "common": true,
    "default": "Expand Image"
  },
  {
    "name": "minimizeImage",
    "type": "text",
    "label": "Minimize Image",
    "importance": "low",
    "common": true,
    "default": "Minimize Image"
  }
]

[
  {
    "name": "files",
    "type": "audio",
    "importance": "high",
    "label": "Source files"
  },
  {
    "name": "playerMode",
    "type": "select",
    "importance": "low",
    "label": "Player mode",
    "description": "Select the layout of the player.",
    "options": [
      {
        "value": "minimalistic",
        "label": "Minimalistic"
      },
      {
        "value": "full",
        "label": "Full"
      },
      {
        "value": "transparent",
        "label": "Transparent"
      }
    ],
    "default": "minimalistic"
  },
  {
    "name": "fitToWrapper",
    "type": "boolean",
    "importance": "low",
    "label": "Fit to wrapper",
    "default": false,
    "descriptions": "Adjust audioplayer size to use available space"
  },
  {
    "name": "controls",
    "type": "boolean",
    "importance": "low",
    "label": "Enable controls",
    "default": true,
    "description": "Controls allow the user to for instance pause the audio"
  },
  {
    "name": "autoplay",
    "type": "boolean",
    "importance": "low",
    "label": "Enable autoplay",
    "description": "With autoplay the audio starts to play immediately. If autoplay is disabled the user presses a play button to start the audio."
  },
  {
    "name": "copyright",
    "type": "group",
    "importance": "low",
    "label": "Copyright information",
    "deprecated": true,
    "optional": true,
    "fields": [
      {
        "name": "title",
        "type": "text",
        "label": "Title",
        "placeholder": "Für Elise",
        "optional": true
      },
      {
        "name": "author",
        "type": "text",
        "label": "Author",
        "placeholder": "Ludwig van Beethoven",
        "optional": true
      },
      {
        "name": "source",
        "type": "text",
        "label": "Source",
        "placeholder": "http://en.wikipedia.org/wiki/F%C3%BCr_Elise",
        "optional": true,
        "regexp": {
          "pattern": "^http[s]?://.+",
          "modifiers": "i"
        }
      },
      {
        "name": "license",
        "type": "select",
        "label": "License",
        "default": "U",
        "options": [
          {
            "value": "U",
            "label": "Undisclosed"
          },
          {
            "value": "CC BY",
            "label": "Attribution"
          },
          {
            "value": "CC BY-SA",
            "label": "Attribution-ShareAlike"
          },
          {
            "value": "CC BY-ND",
            "label": "Attribution-NoDerivs"
          },
          {
            "value": "CC BY-NC",
            "label": "Attribution-NonCommercial"
          },
          {
            "value": "CC BY-NC-SA",
            "label": "Attribution-NonCommercial-ShareAlike"
          },
          {
            "value": "CC BY-NC-ND",
            "label": "Attribution-NonCommercial-NoDerivs"
          },
          {
            "value": "GNU GPL",
            "label": "General Public License"
          },
          {
            "value": "PD",
            "label": "Public Domain"
          },
          {
            "value": "ODC PDDL",
            "label": "Public Domain Dedication and Licence"
          },
          {
            "value": "CC PDM",
            "label": "Public Domain Mark"
          },
          {
            "value": "C",
            "label": "Copyright"
          }
        ]
      }
    ]
  },
  {
    "name": "contentName",
    "type": "text",
    "importance": "low",
    "label": "Audio content name",
    "common": true,
    "default": "Audio"
  },
  {
    "name": "audioNotSupported",
    "type": "text",
    "label": "Audio not supported message",
    "importance": "low",
    "common": true,
    "default": "Your browser does not support this audio"
  }
]

[
  {
    "name": "imageMultipleHotspotQuestion",
    "type": "group",
    "widget": "wizard",
    "label": "Image Multiple Hotspot Question Editor",
    "importance": "high",
    "fields": [
      {
        "name": "backgroundImageSettings",
        "type": "group",
        "label": "Background image",
        "importance": "high",
        "fields": [
          {
            "name": "questionTitle",
            "type": "text",
            "label": "The title of this question",
            "importance": "high",
            "default": "Image hotspot question",
            "description": "Used in summaries, statistics etc."
          },
          {
            "name": "backgroundImage",
            "type": "image",
            "label": "Background image",
            "importance": "high",
            "description": "Select an image to use as background the image hotspot question."
          }
        ]
      },
      {
        "name": "hotspotSettings",
        "type": "group",
        "label": "Hotspots",
        "importance": "high",
        "widget": "imageMultipleHotspotQuestion",
        "description": "Choose appropriate figure for your hotspot, configure it, then drag and resize it into place.",
        "fields": [
          {
            "name": "taskDescription",
            "type": "text",
            "label": "Task description",
            "importance": "high",
            "description": "Instructions to the user.",
            "optional": true
          },
          {
            "name": "hotspotName",
            "type": "text",
            "label": "Hotspot Name",
            "importance": "high",
            "description": "Please enter what the user is trying to find i.e. risks, objects, errors (this will be used in feedback statements).",
            "optional": true
          },
          {
            "name": "numberHotspots",
            "type": "number",
            "label": "Number of correct hotspots that need to be found for question completion",
            "importance": "high",
            "description": "If left blank, will default to the number of correct hotspots created.",
            "optional": true
          },
          {
            "name": "hotspot",
            "type": "list",
            "label": "Hotspot",
            "importance": "high",
            "entity": "Hotspot",
            "field": {
              "type": "group",
              "label": "Hotspot",
              "importance": "high",
              "fields": [
                {
                  "name": "userSettings",
                  "type": "group",
                  "label": "userSettings",
                  "importance": "low",
                  "fields": [
                    {
                      "name": "correct",
                      "type": "boolean",
                      "label": "Correct",
                      "importance": "low",
                      "description": "There can be multiple correct hotspots. The user gets correct/incorrect feedback immediately after each click. The feedback will be displayed in the form of - (Text entered below) (Number of hotspots found) of (Correct hotspots needed) (Hotspot Name entered above)."
                    },
                    {
                      "name": "feedbackText",
                      "type": "text",
                      "label": "Feedback",
                      "importance": "low",
                      "placeholder": "Correct, you have found",
                      "optional": true
                    }
                  ]
                },
                {
                  "name": "computedSettings",
                  "type": "group",
                  "label": "computedSettings",
                  "importance": "low",
                  "fields": [
                    {
                      "name": "x",
                      "type": "number",
                      "optional": true
                    },
                    {
                      "name": "y",
                      "type": "number",
                      "optional": true
                    },
                    {
                      "name": "width",
                      "type": "number",
                      "optional": true
                    },
                    {
                      "name": "height",
                      "type": "number",
                      "optional": true
                    },
                    {
                      "name": "figure",
                      "type": "text",
                      "optional": true
                    }
                  ]
                }
              ]
            }
          },
          {
            "name": "noneSelectedFeedback",
            "type": "text",
            "label": "Feedback if the user selects an empty spot:",
            "importance": "low",
            "placeholder": "You didn't locate any hotspots, try again!",
            "optional": true
          },
          {
            "name": "alreadySelectedFeedback",
            "type": "text",
            "label": "Feedback if the user selects an already found hotspot:",
            "placeholder": "You have already found this one!",
            "importance": "low",
            "optional": true
          }
        ]
      }
    ]
  }
]
